import {forwardKinematics} from '../../src/index.js';
const joint={id:'root',parent:null,x:0,y:0,rotation:0,min:-180,max:180,length:20};
const pack=parts=>({name:'Renderer fixture',spatial:true,joints:[{...joint}],parts,clips:{idle:{duration:1,loop:true,tracks:{}}},inputs:{},initial:'idle',states:{idle:{clip:'idle'}}});
const part=(id,d,fill,spatial={})=>({id,joint:'root',d,fill,stroke:'none',strokeWidth:0,spatial});
export function rendererFixture(lit=false){return {schemaVersion:1,kind:'scene',id:'renderer-fixture',name:'Renderer parity',revision:0,bounds:{width:300,height:200},requiredFeatures:['spatial-rig','scene-depth','scene-objects',...(lit?['scene-lighting']:[])],packs:{shape:pack([part('mask','M-45 0A45 45 0 1 0 45 0A45 45 0 1 0-45 0Z','none'),part('panel','M-60-50H60V50H-60Z','#cf9768',{mask:'mask'}),part('accent','M-20-25Q25-50 33 2Q5 38-30 12Z','#72bfc3',{order:2}),part('mark','M-20 10Q0 28 20 10','none',{order:3})])},actors:[{id:'one',name:'One',pack:'shape',transform:{x:100,y:90,scale:1,rotation:12},depth:{value:100},inputs:{}}],props:[{id:'table',name:'Table',x:210,y:130,width:70,height:25,rotation:-10,fill:'#9d795b',layer:'characters',depth:{value:120},collider:{enabled:false,x:0,y:0,width:70,height:25,bounce:.3,friction:.5}}],objects:[{id:'ball',name:'Ball',shape:'circle',x:200,y:60,radius:14,fill:'#d26455',mass:1,depth:80}],lighting:{enabled:lit,floorShadow:0,wallShadow:0,reflection:0,shading:'cel',receiver:'floor',intensity:.7,ambient:.65,angle:-135,celThickness:.4,celIntensity:.7,gloss:.25,color:'#fff1d6',shadowColor:'#292438',showSource:false}};}
export function rendererFrame(document,pose={},time=0){return {time,effectsTime:time,actors:document.actors.map(actor=>({id:actor.id,pose:{...pose},world:forwardKinematics(document.packs[actor.pack].joints,pose),inputs:{},state:'idle'}))};}
export function crossingMeshFixture(){const mesh=(depths)=>({vertices:[[20,20],[120,20],[20,120]].map(([x,y],i)=>({weights:[{joint:'root',x,y,z:depths[i],weight:1}]})),triangles:[[0,1,2]]});return {schemaVersion:1,kind:'scene',id:'mesh-depth',name:'Crossing mesh depth',revision:0,bounds:{width:140,height:140},requiredFeatures:['spatial-rig','skinned-mesh'],packs:{shape:pack([part('red','M0 0Z','#d94c4c',{mesh:mesh([1,9,1])}),part('blue','M0 0Z','#4c79d9',{mesh:mesh([9,1,9])})])},actors:[{id:'one',name:'One',pack:'shape',transform:{x:0,y:0,scale:1,rotation:0},inputs:{}}]};}
